const fs = require('fs');
const path = require('path');

/**
 * Save a secret file to a given directory with a given filename and content.
 * The file should be accessible only by the current user.
 *
 * @param {string} directory - The directory to save the secret file.
 * @param {string} filename - The filename of the secret file.
 * @param {string} content - The content of the secret file.
 */
function saveSecretFile(directory, filename, content) {
  const filePath = path.join(directory, filename);

  // Validate directory input to prevent path traversal.
  // Ensure the directory is an absolute path and does not contain '..'
  if (!path.isAbsolute(directory) || directory.includes('..')) {
    throw new Error('Invalid directory path. Only absolute paths are allowed and path traversal is prohibited.');
  }

  // Ensure the directory exists with owner-only permissions.
  // On POSIX systems, mkdirSync with recursive: true and mode 0o700
  // ensures the directory is created with owner-only permissions.
  // On Windows, file permissions are managed differently, and ACLs
  // are the primary mechanism. The mode will be ignored, but the
  // file will be created.
  try {
    fs.mkdirSync(directory, {
      recursive: true,
      mode: 0o700
    });
  } catch (err) {
    // If the directory already exists and has appropriate permissions,
    // this is not an error. However, if it exists with restrictive
    // permissions that prevent creation of subdirectories, it might be.
    // For simplicity, we'll proceed if the directory exists.
    if (err.code !== 'EEXIST') {
      throw err;
    }
  }

  // Write the file with permissions that restrict access to the owner.
  // On POSIX systems, mode 0o600 grants read/write permissions to the owner only.
  // On Windows, this mode is advisory and the OS's ACLs will govern access.
  // For true cross-platform owner-only access on Windows, ACL manipulation
  // would be required, which is beyond the scope of standard fs.writeFileSync.
  // We rely on the OS's default behavior for user-specific access.
  fs.writeFileSync(filePath, content, {
    mode: 0o600
  });
}
